        ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
        // Add glow for larger stars
        if (this.size > 1.5) {
            ctx.shadowBlur = this.size * 2;
            ctx.shadowColor = `rgba(200, 220, 255, ${alpha * 0.5})`;
            ctx.fill();
            ctx.shadowBlur = 0;
        }
    }
