class NebulaParticle {
    constructor() {
        this.reset();
        // Random initial position
        this.x = Math.random() * width;
        this.y = Math.random() * height;
    }

    reset() {
        this.radius = Math.random() * 250 + 100;
        // Colors: purples, pinks, blues, teals
        const hue = Math.random() < 0.7 ? 
            Math.random() * 60 + 260 : // 260-320: purple to pink
            Math.random() * 40 + 200;   // 200-240: blue to teal
        this.color = `hsla(${hue}, 70%, 50%, ${Math.random() * 0.15 + 0.05})`;
        this.driftX = (Math.random() - 0.5) * 0.3;
        this.driftY = (Math.random() - 0.5) * 0.3;
    }

    update() {
        this.x += this.driftX;
        this.y += this.driftY;
        // Wrap around screen
        if (this.x < -this.radius) this.x = width + this.radius;
        if (this.x > width + this.radius) this.x = -this.radius;
        if (this.y < -this.radius) this.y = height + this.radius;
        if (this.y > height + this.radius) this.y = -this.radius;
    }

    draw() {
        const gradient = ctx.createRadialGradient(
            this.x, this.y, 0,
            this.x, this.y, this.radius
        );
        gradient.addColorStop(0, this.color);
        gradient.addColorStop(1, 'transparent');
        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fill();
    }
}

